import 'dart:convert';
import 'dart:io';

const _languages = ['en', 'zh', 'ja', 'ru', 'fr', 'es', 'ko'];

String _literal(String text) =>
    "'${text.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$')}'";

Future<void> main(List<String> args) async {
  if (args.length != 1) {
    throw ArgumentError('Expected the directory of CLDR 46.1.0 language files');
  }
  final result = StringBuffer(
    '''// Generated by tool/generate_country_names.dart from Unicode CLDR 46.1.0.
// Copyright © 2015-2024 Unicode, Inc. See assets/data/Unicode-CLDR-LICENSE.txt.

String? countryName(String? countryCode, String languageCode) {
  final code = countryCode?.trim().toUpperCase();
  return _names[languageCode]?[code] ?? _names['en']?[code];
}

const _names = <String, Map<String, String>>{
''',
  );
  for (final language in _languages) {
    final json =
        jsonDecode(await File('${args.single}/$language.json').readAsString())
            as Map<String, dynamic>;
    final names =
        json['main'][language]['localeDisplayNames']['territories']
            as Map<String, dynamic>;
    final codes =
        names.keys
            .where(
              (code) => RegExp(r'^[A-Z]{2}$').hasMatch(code) && code != 'ZZ',
            )
            .toList()
          ..sort();
    result.writeln('  ${_literal(language)}: {');
    for (final code in codes) {
      result.writeln(
        '    ${_literal(code)}: ${_literal(names[code] as String)},',
      );
    }
    result.writeln('  },');
  }
  result.writeln('};');
  await File('lib/common/country_names.dart').writeAsString(result.toString());
}
